question.solution:
def rob_line(nums):
    prev, curr = 0, 0
    for x in nums:
        prev, curr = curr, max(curr, prev + x)
    return curr


def rob_circle(nums):
    values = [int(x) for x in (nums or [])]
    if not values:
        return 0
    if len(values) == 1:
        return values[0]
    return max(rob_line(values[:-1]), rob_line(values[1:]))


print(rob_circle([2, 3, 2]))
print(rob_circle([1, 2, 3, 1]))
print(rob_circle([1, 2, 3]))
